class Solution {
    public ListNode sortCars(ListNode head) {
        List<Integer> vals = new ArrayList<>();
        for (ListNode n = head; n != null; n = n.next) vals.add(n.val);
        Collections.sort(vals);
        ListNode n = head;
        for (int v : vals) { n.val = v; n = n.next; }
        return head;
    }
}

