static int cmp(const void* x, const void* y) {
    int a = *(const int*) x, b = *(const int*) y;
    return (a > b) - (a < b);
}

struct ListNode* sortCars(struct ListNode* head) {
    int n = 0;
    for (struct ListNode* p = head; p; p = p->next) n++;
    int* vals = malloc((n + 1) * sizeof(int));
    int i = 0;
    for (struct ListNode* p = head; p; p = p->next) vals[i++] = p->val;
    qsort(vals, n, sizeof(int), cmp);
    i = 0;
    for (struct ListNode* p = head; p; p = p->next) p->val = vals[i++];
    free(vals);
    return head;
}

